"use client";

import { useState, useEffect } from "react";
import { Card, CardHeader, CardContent, CardFooter, Input, Button } from "@/components/ui";
import { useAuth } from "@/contexts/AuthContext";
import { usersApi, UpdateUserDto } from "@/lib/api/users";
import { CheckCircle2, AlertCircle, Loader2, Upload, X } from "lucide-react";
import { uploadProfileImage, deleteProfileImage } from "@/lib/api/users";

export function UserProfileSettings() {
  const { productUser } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [success, setSuccess] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    first_name: "",
    last_name: "",
    email: "",
  });

  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [uploadedImageUrl, setUploadedImageUrl] = useState<string | null>(null);

  useEffect(() => {
    if (productUser) {
      setFormData({
        first_name: productUser.first_name || "",
        last_name: productUser.last_name || "",
        email: productUser.email || "",
      });
      if (productUser.profile_image) {
        setImagePreview(productUser.profile_image);
      }
    }
  }, [productUser]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    setSuccess(null);
    setError(null);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
    if (!allowedTypes.includes(file.type)) {
      setError('Invalid file type. Please select an image file (JPEG, PNG, GIF, or WebP).');
      return;
    }

    // Validate file size (5MB)
    if (file.size > 5 * 1024 * 1024) {
      setError('File size exceeds 5MB limit.');
      return;
    }

    setSelectedImage(file);
    setError(null);
    setSuccess(null);

    // Create preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setImagePreview(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setSelectedImage(null);
    setImagePreview(productUser?.profile_image || null);
    setUploadedImageUrl(null);
    setError(null);
  };

  const handleImageUpload = async () => {
    if (!selectedImage || !productUser) return;

    setIsUploading(true);
    setError(null);

    try {
      // Upload using the same pattern as admin panel
      const newImageUrl = await uploadProfileImage(productUser.id, selectedImage);
      
      // Delete old image if it exists
      if (productUser.profile_image) {
        await deleteProfileImage(productUser.profile_image);
      }

      setUploadedImageUrl(newImageUrl);
      setSuccess('Image uploaded successfully! Click "Save Changes" to update your profile.');
    } catch (err) {
      setError(
        err instanceof Error ? err.message : 'Failed to upload image'
      );
    } finally {
      setIsUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!productUser) return;

    setIsSaving(true);
    setSuccess(null);
    setError(null);

    try {
      const updateData: UpdateUserDto = {
        first_name: formData.first_name,
        last_name: formData.last_name,
        email: formData.email,
      };

      // Include uploaded image URL if available
      if (uploadedImageUrl) {
        updateData.profile_image = uploadedImageUrl;
      }

      const response = await usersApi.update(productUser.id, updateData);

      if (response.success || response.data) {
        setSuccess("Profile updated successfully!");
        // Reset image selection
        setSelectedImage(null);
        setUploadedImageUrl(null);
        // Refresh user data by reloading the page or refetching
        setTimeout(() => {
          window.location.reload();
        }, 1500);
      } else {
        setError("Failed to update profile. Please try again.");
      }
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to update profile"
      );
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent>
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-6 w-6 animate-spin text-slate-400" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader
        title="Profile Information"
        description="Update your personal information and contact details"
      />
      <form onSubmit={handleSubmit}>
        <CardContent className="space-y-4">
          {/* Success Message */}
          {success && (
            <div className="rounded-lg bg-success-500/10 border border-success-500/30 p-4 flex items-center gap-3">
              <CheckCircle2 className="h-5 w-5 text-success-500 flex-shrink-0" />
              <p className="text-sm text-success-500">{success}</p>
            </div>
          )}

          {/* Error Message */}
          {error && (
            <div className="rounded-lg bg-danger-500/10 border border-danger-500/30 p-4 flex items-center gap-3">
              <AlertCircle className="h-5 w-5 text-danger-500 flex-shrink-0" />
              <p className="text-sm text-danger-500">{error}</p>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label
                htmlFor="first_name"
                className="block text-sm font-medium text-slate-300 mb-2"
              >
                First Name
              </label>
              <Input
                id="first_name"
                name="first_name"
                type="text"
                value={formData.first_name}
                onChange={handleChange}
                required
                placeholder="Enter your first name"
              />
            </div>

            <div>
              <label
                htmlFor="last_name"
                className="block text-sm font-medium text-slate-300 mb-2"
              >
                Last Name
              </label>
              <Input
                id="last_name"
                name="last_name"
                type="text"
                value={formData.last_name}
                onChange={handleChange}
                required
                placeholder="Enter your last name"
              />
            </div>
          </div>

          <div>
            <label
              htmlFor="email"
              className="block text-sm font-medium text-slate-300 mb-2"
            >
              Email Address
            </label>
            <Input
              id="email"
              name="email"
              type="email"
              value={formData.email}
              onChange={handleChange}
              required
              placeholder="Enter your email address"
            />
          </div>

          {/* Profile Image Section */}
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              Profile Image
            </label>
            <div className="flex items-center gap-4">
              {imagePreview ? (
                <div className="relative">
                  <img
                    src={imagePreview}
                    alt="Profile"
                    className="h-20 w-20 rounded-full object-cover border-2 border-[#B87333]/30"
                  />
                  {selectedImage && (
                    <button
                      type="button"
                      onClick={handleRemoveImage}
                      className="absolute -top-2 -right-2 bg-danger-500 text-white rounded-full p-1 hover:bg-danger-600 transition-colors"
                      title="Remove selected image"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  )}
                </div>
              ) : (
                <div className="h-20 w-20 rounded-full bg-gradient-to-br from-[#B87333]/20 to-[#DA8A67]/10 border-2 border-[#B87333]/30 flex items-center justify-center text-2xl font-semibold text-[#DA8A67]">
                  {productUser?.first_name?.[0]?.toUpperCase() || "U"}
                </div>
              )}
              <div className="flex-1 space-y-2">
                <div className="flex items-center gap-2">
                  <label className="cursor-pointer">
                    <input
                      type="file"
                      accept="image/jpeg,image/jpg,image/png,image/gif,image/webp"
                      onChange={handleImageSelect}
                      className="hidden"
                      disabled={isUploading}
                    />
                    <div className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-slate-800 border border-slate-700 text-slate-300 hover:bg-slate-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                      <Upload className="h-4 w-4" />
                      <span className="text-sm">
                        {selectedImage ? "Change Image" : "Upload Image"}
                      </span>
                    </div>
                  </label>
                  {selectedImage && !uploadedImageUrl && (
                    <Button
                      type="button"
                      onClick={handleImageUpload}
                      disabled={isUploading}
                    >
                      {isUploading ? (
                        <>
                          <Loader2 className="h-4 w-4 animate-spin mr-2" />
                          Uploading...
                        </>
                      ) : (
                        "Upload"
                      )}
                    </Button>
                  )}
                </div>
                <p className="text-xs text-slate-400">
                  JPEG, PNG, GIF, or WebP (max 5MB)
                </p>
              </div>
            </div>
          </div>
        </CardContent>

        <CardFooter>
          <Button type="submit" disabled={isSaving || isUploading}>
            {isSaving ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
                Saving...
              </>
            ) : (
              "Save Changes"
            )}
          </Button>
        </CardFooter>
      </form>
    </Card>
  );
}
